import journal from '@/data/journal.json';
import assets from '@/data/assets.json';

// The Journal (docs/design/phase-c4-1b-journal.md). Two voices, kept apart in the data and on the page:
// `morph` is Morph's own wording, quoted with its source (data/journal.json, generated by `npm run journal`);
// everything written here is the concept's: labels, summaries of verified facts, dated notes, captions, alt text.
// Morph articles are not reproduced: the page quotes a short excerpt and links to the full text on morphparfum.ro.

type Source = (typeof journal.entries)[number];
export type JournalImage = { src: string; alt: string; w: number; h: number; caption?: string };
export type JournalEntry = {
  key: string;
  slug: string;
  type: 'Articol Morph' | 'Campanie';
  title: string;
  /** display only: set the part after the colon as a smaller second line, and keep hyphenated words whole */
  titleBreak?: boolean;
  /** publication date (ISO), for Morph articles only; the campaign page carries no date */
  date?: string;
  source: Source['source'];
  excerpt: { voice: 'morph'; text: string };
  /** concept: one line for the index and the article head */
  lede: string;
  /** concept: the verified facts of the source, in order */
  summary: string[];
  /** concept: facts that have changed since the source was written, or that the source leaves out */
  notes: string[];
  lead: JournalImage;
  image?: JournalImage;
  related: { href: string; label: string }[];
};

export const MORPH_BLOG = journal.blog;
const src = (key: string) => journal.entries.find(e => e.key === key)!;
const J1 = src('your-next-form'), J2 = src('workshop-layering'), J3 = src('primitivo');
const J1_SLUG = J1.source.slug!, J2_SLUG = J2.source.slug!;

