/** where a Journal image comes from in Morph's media library (data/assets.json) */
export const imageSource = (src: string) => {
  const a = assets.assets.find(x => src.endsWith('/' + x.file));
  return a && a.status === 'concept' ? assets.base + a.src : null;
};

export const bySlug = (slug: string) => ENTRIES.find(e => e.slug === slug) ?? null;
export const journalHref = (key: string) => `/jurnal/${ENTRIES.find(e => e.key === key)!.slug}`;
export const longDate = (iso: string) => new Date(`${iso}T12:00:00Z`).toLocaleDateString('ro-RO', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' });
